const markPullRequestMerged = `-- name: MarkPullRequestMerged :execrows
UPDATE pull_requests
SET state = 'merged', merge_method = $1, merge_sha = $2,
    merge_base_sha = $3, head_sha = $4,
    merged_by = $5, merged_at = NOW(), updated_at = NOW()
WHERE id = $6 AND state = 'open'
`

type MarkPullRequestMergedParams struct {
	MergeMethod  *string     `json:"merge_method"`
	MergeSha     *string     `json:"merge_sha"`
	MergeBaseSha *string     `json:"merge_base_sha"`
	HeadSha      string      `json:"head_sha"`
	MergedBy     pgtype.UUID `json:"merged_by"`
	ID           pgtype.UUID `json:"id"`
}

func (q *Queries) MarkPullRequestMerged(ctx context.Context, arg MarkPullRequestMergedParams) (int64, error) {
	result, err := q.db.Exec(ctx, markPullRequestMerged,
		arg.MergeMethod,
		arg.MergeSha,
		arg.MergeBaseSha,
		arg.HeadSha,
		arg.MergedBy,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const nextPullNumber = `-- name: NextPullNumber :one

UPDATE repositories SET next_pull_number = next_pull_number + 1
WHERE id = $1
RETURNING (next_pull_number - 1)::int AS number
`

// ─── Pull requests (D-75) ────────────────────────────────────────────────────
func (q *Queries) NextPullNumber(ctx context.Context, id pgtype.UUID) (int32, error) {
	row := q.db.QueryRow(ctx, nextPullNumber, id)
	var number int32
	err := row.Scan(&number)
	return number, err
}

