const upsertAgentBranch = `-- name: UpsertAgentBranch :exec
INSERT INTO agent_branches (repository_id, name, connection_id, user_id, token_hash, token_expires_at)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (repository_id, name) DO UPDATE
SET token_hash = EXCLUDED.token_hash, token_expires_at = EXCLUDED.token_expires_at
WHERE agent_branches.connection_id = EXCLUDED.connection_id
`

type UpsertAgentBranchParams struct {
	RepositoryID   pgtype.UUID        `json:"repository_id"`
	Name           string             `json:"name"`
	ConnectionID   pgtype.UUID        `json:"connection_id"`
	UserID         pgtype.UUID        `json:"user_id"`
	TokenHash      string             `json:"token_hash"`
	TokenExpiresAt pgtype.Timestamptz `json:"token_expires_at"`
}

// A new push credential for an agent's branch: the first, or the next one
// create_branch issues on the same branch for the same connection.
func (q *Queries) UpsertAgentBranch(ctx context.Context, arg UpsertAgentBranchParams) error {
	_, err := q.db.Exec(ctx, upsertAgentBranch,
		arg.RepositoryID,
		arg.Name,
		arg.ConnectionID,
		arg.UserID,
		arg.TokenHash,
		arg.TokenExpiresAt,
	)
	return err
}

const upsertCommitCheck = `-- name: UpsertCommitCheck :one
INSERT INTO commit_checks (repository_id, sha, name, state, description, details_url, deployment_id, reporter_id, started_at, completed_at)
VALUES ($1, $2, $3, $4, $5,
        $6, $7, $8,
        CASE WHEN $4::text = 'pending' THEN NULL ELSE NOW() END,
        CASE WHEN $4::text IN ('success', 'failure', 'cancelled', 'skipped') THEN NOW() END)
ON CONFLICT (repository_id, sha, name) DO UPDATE SET
    state         = EXCLUDED.state,
    description   = EXCLUDED.description,
    details_url   = EXCLUDED.details_url,
    deployment_id = EXCLUDED.deployment_id,
    reporter_id   = EXCLUDED.reporter_id,
    started_at    = CASE WHEN EXCLUDED.state = 'pending' THEN NULL
                         WHEN commit_checks.started_at IS NULL OR commit_checks.completed_at IS NOT NULL THEN NOW()
                         ELSE commit_checks.started_at END,
    completed_at  = EXCLUDED.completed_at,
    updated_at    = NOW()
RETURNING created_at, updated_at, started_at, completed_at
`

type UpsertCommitCheckParams struct {
	RepositoryID pgtype.UUID `json:"repository_id"`
	Sha          string      `json:"sha"`
	Name         string      `json:"name"`
	State        string      `json:"state"`
	Description  string      `json:"description"`
	DetailsUrl   *string     `json:"details_url"`
	DeploymentID pgtype.UUID `json:"deployment_id"`
	ReporterID   pgtype.UUID `json:"reporter_id"`
}

type UpsertCommitCheckRow struct {
	CreatedAt   pgtype.Timestamptz `json:"created_at"`
	UpdatedAt   pgtype.Timestamptz `json:"updated_at"`
	StartedAt   pgtype.Timestamptz `json:"started_at"`
	CompletedAt pgtype.Timestamptz `json:"completed_at"`
}

// Reported again by name, a check is updated: started_at is set when it
// first runs (again after it had ended), completed_at when it ends.
func (q *Queries) UpsertCommitCheck(ctx context.Context, arg UpsertCommitCheckParams) (UpsertCommitCheckRow, error) {
	row := q.db.QueryRow(ctx, upsertCommitCheck,
		arg.RepositoryID,
		arg.Sha,
		arg.Name,
		arg.State,
		arg.Description,
		arg.DetailsUrl,
		arg.DeploymentID,
		arg.ReporterID,
	)
	var i UpsertCommitCheckRow
	err := row.Scan(
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.StartedAt,
		&i.CompletedAt,
	)
	return i, err
}
